namespace Orbyss.Foundation.Web.Presentation;

/// <summary>Immutable presentation input; the only markup is generated by native controls, never request or provider content.</summary>
public sealed class AdmittedBrowserRecoveryPage
{
    /// <summary>Builds a page model after native copy, paths, session observations and controls have been admitted.</summary>
    internal AdmittedBrowserRecoveryPage(BrowserPresentationCatalog catalog, BrowserPresentationText text, string title, string bodyHtml, string pathBase, bool? hasLocalSession)
    {
        ApplicationName = catalog.ApplicationName; Locale = text.Locale; Theme = catalog.Theme;
        Title = title; BodyHtml = bodyHtml; HomePath = pathBase + catalog.ReturnPath;
        HomeLabel = text.Copy["home"]; StylesheetPath = pathBase + catalog.RoutePrefix + "/assets/v1/page.css";
        FocusModulePath = pathBase + catalog.RoutePrefix + "/assets/v1/recovery-focus.mjs";
        HasLocalSession = hasLocalSession;
    }
    /// <summary>Gets the plain application name.</summary>
    public string ApplicationName { get; }
    /// <summary>Gets the selected canonical language.</summary>
    public string Locale { get; }
    /// <summary>Gets the validated theme token.</summary>
    public string Theme { get; }
    /// <summary>Gets the plain title, requiring output encoding.</summary>
    public string Title { get; }
    /// <summary>Gets native generated safe markup, including an antiforgery form when applicable. Preserve that form rather than creating authentication controls.</summary>
    public string BodyHtml { get; }
    /// <summary>Gets the admitted native application destination.</summary>
    public string HomePath { get; }
    /// <summary>Gets its plain localized label.</summary>
    public string HomeLabel { get; }
    /// <summary>Gets the anonymously served stylesheet URL.</summary>
    public string StylesheetPath { get; }
    /// <summary>Gets the anonymous CSP-compatible module that focuses recovery when the application window becomes active.</summary>
    public string FocusModulePath { get; }
    /// <summary>Gets independently observed local-session state; null means unobserved, never provider logout.</summary>
    public bool? HasLocalSession { get; }
}
